#!/usr/bin/env python3
# Apply outbound MTA routes declared in build.json#mta_routes to a running
# Stalwart v0.16+ instance via the JMAP `urn:stalwart:jmap` capability.
#
# Inputs (all positional):
#   argv[1] : routes JSON file (data-only — flake emits this from build.json)
#   argv[2] : Stalwart base URL (e.g. https://10.0.0.3:2443)
#   argv[3] : "<admin-user>:<password>" (admin-role user with JMAP access)
#   argv[4] : secrets-dir (one file per env-var name)
#
# Idempotent: existing routes (matched by `name`) are updated; new ones are
# created. Routes flagged `default_outbound:true` rewrite the singleton
# MtaOutboundStrategy.route.else expression to relay all non-local mail.
#
# Schema sourced from stalwartlabs/stalwart:
#   crates/registry/src/schema/structs.rs::SecretKeyOptional
#   crates/jmap/src/registry/{get,set}.rs
import sys, json, ssl, os, base64
from urllib import request as ur, error as ue

if len(sys.argv) < 5:
    print("usage: apply-mta-routes.py <routes.json> <base-url> <user:pass> <secrets-dir>", file=sys.stderr)
    sys.exit(2)

routes_path, base, auth, secrets_dir = sys.argv[1:5]
with open(routes_path) as f:
    routes = json.load(f)

if not routes:
    print("  (no mta_routes declared — skipping)")
    sys.exit(0)

ctx = ssl.create_default_context()
ctx.check_hostname = False
ctx.verify_mode = ssl.CERT_NONE

AUTH_HEADER = "Basic " + base64.b64encode(auth.encode()).decode()

def jmap(calls):
    body = json.dumps({
        "using": ["urn:ietf:params:jmap:core", "urn:stalwart:jmap"],
        "methodCalls": calls,
    }).encode()
    req = ur.Request(base + "/jmap/", data=body, method="POST",
        headers={"Content-Type": "application/json", "Authorization": AUTH_HEADER})
    try:
        return json.loads(ur.urlopen(req, context=ctx, timeout=15).read())
    except ue.HTTPError as e:
        return {"error": e.code, "body": e.read().decode(errors='replace')[:400]}

def read_secret(var):
    if not var: return None
    p = os.path.join(secrets_dir, var)
    try:
        with open(p) as f: return f.read().strip()
    except FileNotFoundError:
        print("  [warn] missing secret file:", p)
        return None

def discover_account():
    req = ur.Request(base + "/jmap/session", method="GET",
        headers={"Authorization": AUTH_HEADER})
    try:
        s = json.loads(ur.urlopen(req, context=ctx, timeout=10).read())
    except ue.HTTPError as e:
        print(f"  [FAIL] /jmap/session: HTTP {e.code} (auth identity has no JMAP access?)")
        return None
    pa = s.get("primaryAccounts", {})
    return (pa.get("urn:stalwart:jmap")
            or pa.get("urn:ietf:params:jmap:mail")
            or next(iter(s.get("accounts", {})), None))

acct = discover_account()
if not acct:
    sys.exit(1)

# Snapshot existing MtaRoute objects keyed by name.
r = jmap([["x:MtaRoute/get", {"accountId": acct, "ids": None}, "0"]])
mr = r.get("methodResponses") or []
existing = (mr[0][1].get("list") if mr else []) or []
by_name = {x.get("name"): x.get("id") for x in existing if x.get("name")}

default_route_name = None
exit_code = 0
for route in routes:
    name = route["name"]
    user = read_secret(route.get("auth_username_env"))
    pw   = read_secret(route.get("auth_secret_env"))
    payload = {
        "@type": "Relay",
        "address": route["address"],
        "port": int(route["port"]),
        "name": name,
        "protocol": route.get("protocol", "smtp"),
        "implicitTls": bool(route.get("implicit_tls", False)),
        "allowInvalidCerts": bool(route.get("allow_invalid_certs", False)),
    }
    if route.get("description"): payload["description"] = route["description"]
    if user: payload["authUsername"] = user
    if pw:   payload["authSecret"] = {"@type": "Value", "secret": pw}

    if name in by_name:
        rid = by_name[name]
        rr = jmap([["x:MtaRoute/set", {"accountId": acct, "update": {rid: payload}}, "0"]])
        u = (rr.get("methodResponses") or [[None,{}]])[0][1]
        if u.get("updated"):
            print(f"  updated route '{name}' (id={rid})")
        else:
            print(f"  FAIL update '{name}': {u.get('notUpdated') or rr}")
            exit_code = 1
    else:
        rr = jmap([["x:MtaRoute/set", {"accountId": acct, "create": {"new": payload}}, "0"]])
        c = (rr.get("methodResponses") or [[None,{}]])[0][1]
        if c.get("created"):
            print(f"  created route '{name}'")
        else:
            print(f"  FAIL create '{name}': {c.get('notCreated') or rr}")
            exit_code = 1

    if route.get("default_outbound"):
        default_route_name = name

# Wire MtaOutboundStrategy.route.else → '<default-route-name>' (singleton).
if default_route_name:
    strat_route = {"match": [], "else": "'" + default_route_name + "'"}
    rr = jmap([["x:MtaOutboundStrategy/set", {"accountId": acct,
        "create": {"new": {"route": strat_route}}}, "0"]])
    s = (rr.get("methodResponses") or [[None,{}]])[0][1]
    if s.get("created"):
        print(f"  MtaOutboundStrategy.route.else = '{default_route_name}'")
    else:
        rr = jmap([["x:MtaOutboundStrategy/get", {"accountId": acct, "ids": None}, "0"]])
        items = ((rr.get("methodResponses") or [[None,{}]])[0][1].get("list") or [])
        if items:
            sid = items[0]["id"]
            rr = jmap([["x:MtaOutboundStrategy/set", {"accountId": acct,
                "update": {sid: {"route": strat_route}}}, "0"]])
            u = (rr.get("methodResponses") or [[None,{}]])[0][1]
            if u.get("updated"):
                print(f"  updated MtaOutboundStrategy → '{default_route_name}'")
            else:
                print(f"  FAIL update strategy: {u.get('notUpdated') or rr}")
                exit_code = 1
        else:
            print(f"  FAIL: strategy not created and not found")
            exit_code = 1

sys.exit(exit_code)
